import json

C = []
def card(g, q, pts, need=None, fix=None, arkan=False):
    n = len(pts)
    if need is None:
        need = n if (arkan or n <= 8) else max(3, (n + 1) // 2)
    c = {"id": f"m{len(C)+1}", "g": g, "q": q, "pts": pts, "need": need}
    if fix: c["fix"] = fix
    C.append(c)

